package pe.com.dentalamericana.finance;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;@Entity@Table(name="cuentas_por_cobrar")public class ReceivableAccount{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="plan_id",nullable=false,unique=true)private Long planId;@Column(name="paciente_id",nullable=false)private Long patientId;@Column(name="monto_total",nullable=false)private BigDecimal totalAmount;@Column(name="monto_pagado",nullable=false)private BigDecimal paidAmount=BigDecimal.ZERO;@Column(nullable=false)private BigDecimal saldo;@Enumerated(EnumType.STRING)@Column(nullable=false)private ReceivableStatus estado;@Column(name="fecha_vencimiento")private LocalDate dueDate;@Column(name="creado_en",nullable=false)private Instant createdAt;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;@Version private Long version;protected ReceivableAccount(){}public ReceivableAccount(Long planId,Long patientId,BigDecimal total){this.planId=planId;this.patientId=patientId;this.totalAmount=total;this.saldo=total;this.estado=total.signum()==0?ReceivableStatus.PAGADA:ReceivableStatus.PENDIENTE;}public void updateTotal(BigDecimal total){if(total.compareTo(paidAmount)<0)throw new IllegalStateException("El total no puede ser menor que lo pagado");this.totalAmount=total;this.saldo=total.subtract(paidAmount);refresh();}public void registerPayment(BigDecimal amount){paidAmount=paidAmount.add(amount);saldo=totalAmount.subtract(paidAmount);refresh();}public void reversePayment(BigDecimal amount){paidAmount=paidAmount.subtract(amount);saldo=totalAmount.subtract(paidAmount);refresh();}private void refresh(){estado=saldo.signum()==0?ReceivableStatus.PAGADA:paidAmount.signum()>0?ReceivableStatus.PARCIAL:ReceivableStatus.PENDIENTE;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public Long getPlanId(){return planId;}public Long getPatientId(){return patientId;}public BigDecimal getTotalAmount(){return totalAmount;}public BigDecimal getPaidAmount(){return paidAmount;}public BigDecimal getBalance(){return saldo;}public ReceivableStatus getStatus(){return estado;}public LocalDate getDueDate(){return dueDate;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Long getVersion(){return version;}}
